36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.assignment.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.assignment.HouseholdIdGenerator;
40	import org.springframework.samples.petclinic.rest.assignment.HouseholdSizeCalculator;
41	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
42	import org.springframework.samples.petclinic.rest.signup.BulkSignupWarningEvaluator;
43	import org.springframework.samples.petclinic.rest.validation.AddressFormNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitValidator;
45	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitValidator;
46	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainValidator;
47	import org.springframework.samples.petclinic.rest.validation.DuplicateOwnerValidator;
48	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
49	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
50	import org.springframework.samples.petclinic.rest.validation.PossibleDuplicateDetector;
51	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
52	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
53	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final OwnerRequestValidator ownerRequestValidator;
81	
82	    private final PostcodeValidator postcodeValidator;
83	
84	    private final DuplicateOwnerValidator duplicateOwnerValidator;
85	
86	    private final PossibleDuplicateDetector possibleDuplicateDetector;
87	
88	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
89	
90	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
91	
92	    private final RegistrationDateValidator registrationDateValidator;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final EmailNormalizer emailNormalizer;
97	
98	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
99	
100	    private final AddressFormNormalizer addressFormNormalizer;
101	
102	    private final CustomerCodeGenerator customerCodeGenerator;
103	
104	    private final HouseholdIdGenerator householdIdGenerator;
105	
106	    private final HouseholdSizeCalculator householdSizeCalculator;
107	
108	    private final OwnerAuditLogger ownerAuditLogger;
109	
110	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 OwnerRequestValidator ownerRequestValidator,
117	                                 PostcodeValidator postcodeValidator,
118	                                 DuplicateOwnerValidator duplicateOwnerValidator,
119	                                 PossibleDuplicateDetector possibleDuplicateDetector,
120	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
121	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
122	                                 RegistrationDateValidator registrationDateValidator,
123	                                 TelephoneNormalizer telephoneNormalizer,
124	                                 EmailNormalizer emailNormalizer,
125	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
126	                                 AddressFormNormalizer addressFormNormalizer,
127	                                 CustomerCodeGenerator customerCodeGenerator,
128	                                 HouseholdIdGenerator householdIdGenerator,
129	                                 HouseholdSizeCalculator householdSizeCalculator,
130	                                 OwnerAuditLogger ownerAuditLogger,
131	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator) {
132	        this.clinicService = clinicService;
133	        this.ownerMapper = ownerMapper;
134	        this.petMapper = petMapper;
135	        this.visitMapper = visitMapper;
136	        this.ownerRequestValidator = ownerRequestValidator;
137	        this.postcodeValidator = postcodeValidator;
138	        this.duplicateOwnerValidator = duplicateOwnerValidator;
139	        this.possibleDuplicateDetector = possibleDuplicateDetector;
140	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
141	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
142	        this.registrationDateValidator = registrationDateValidator;
143	        this.telephoneNormalizer = telephoneNormalizer;
144	        this.emailNormalizer = emailNormalizer;
145	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
146	        this.addressFormNormalizer = addressFormNormalizer;
147	        this.customerCodeGenerator = customerCodeGenerator;
148	        this.householdIdGenerator = householdIdGenerator;
149	        this.householdSizeCalculator = householdSizeCalculator;
150	        this.ownerAuditLogger = ownerAuditLogger;
151	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
152	    }
153	
154	    /**
155	     * Map an owner to its DTO and stamp the current bulk-signup warning onto it, so every
156	     * single-owner response reflects whether more than 80 owners have been created today.
157	     */
158	    private OwnerDto toOwnerDto(Owner owner) {
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
161	        return ownerDto;
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
167	        Collection<Owner> owners;
168	        if (lastName != null) {
169	            owners = this.clinicService.findOwnerByLastName(lastName);
170	        } else {
171	            owners = this.clinicService.findAllOwners();
172	        }
173	        if (owners.isEmpty()) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
192	        this.addressFormNormalizer.normalize(ownerFieldsDto);
193	        this.ownerRequestValidator.validate(ownerFieldsDto);
194	        this.postcodeValidator.validate(ownerFieldsDto);
195	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
196	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
197	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
198	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
199	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
200	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
201	        HttpHeaders headers = new HttpHeaders();
202	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
203	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
204	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
205	        // identifier of its household automatically.
206	        owner.setHouseholdId(
207	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
208	        if (sharesHousehold) {
209	            // A declared household member is deliberately allowed and, being declared, is never a
210	            // suspected duplicate.
211	            owner.setPossibleDuplicate(false);
212	            owner.setPossibleDuplicateOf(null);
213	        } else {
214	            this.duplicateOwnerValidator.validate(owner);
215	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
216	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
217	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
218	        }
219	        owner.setCustomerCode(
220	            this.customerCodeGenerator.generate(owner.getPostcode(), owner.getTelephone(),
221	                owner.getLastName()));
222	        owner.setNamesakeCount(
223	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
224	        owner.setHouseholdSize(this.householdSizeCalculator.size(owner));
225	        this.clinicService.saveOwner(owner);
226	        this.ownerAuditLogger.created(owner);
227	        OwnerDto ownerDto = toOwnerDto(owner);
228	        headers.setLocation(UriComponentsBuilder.newInstance()
229	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
230	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
236	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
237	        if (currentOwner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        currentOwner.setAddress(ownerFieldsDto.getAddress());
241	        currentOwner.setCity(ownerFieldsDto.getCity());
242	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
243	        currentOwner.setLastName(ownerFieldsDto.getLastName());
244	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
245	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
246	        this.clinicService.saveOwner(currentOwner);
247	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
248	    }
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Transactional
252	    @Override
253	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
254	        Owner owner = this.clinicService.findOwnerById(ownerId);
255	        if (owner == null) {
256	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	        }
258	        this.clinicService.deleteOwner(owner);
259	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
265	        Owner owner = this.clinicService.findOwnerById(ownerId);
266	        if (owner == null) {
267	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	        }
269	        HttpHeaders headers = new HttpHeaders();
270	        Pet pet = petMapper.toPet(petFieldsDto);
271	        owner.setId(ownerId);
272	        pet.setOwner(owner);
273	        pet.getType().setName(null);
274	        this.clinicService.savePet(pet);
275	        PetDto petDto = petMapper.toPetDto(pet);
276	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
277	            .buildAndExpand(pet.getId()).toUri());
278	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
284	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
285	        if (currentOwner != null) {
286	            Pet currentPet = this.clinicService.findPetById(petId);
287	            if (currentPet != null) {
288	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
289	                currentPet.setName(petFieldsDto.getName());
290	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
291	                this.clinicService.savePet(currentPet);
292	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
293	            }
294	        }
295	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	    }
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
301	        HttpHeaders headers = new HttpHeaders();
302	        Visit visit = visitMapper.toVisit(visitFieldsDto);
303	        Pet pet = new Pet();
304	        pet.setId(petId);
305	        visit.setPet(pet);
306	        this.clinicService.saveVisit(visit);
307	        VisitDto visitDto = visitMapper.toVisitDto(visit);
308	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
309	            .buildAndExpand(visit.getId()).toUri());
310	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
311	    }
312	
313	
314	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
315	    @Override
316	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
317	        Owner owner = this.clinicService.findOwnerById(ownerId);
318	        if (owner != null) {
319	            Pet pet = owner.getPet(petId);
320	            if (pet != null) {
321	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
322	            }
323	        }
324	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	    }
326	}
