16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "address_line1")
45	    private String addressLine1;
46	
47	    @Column(name = "address_line2")
48	    private String addressLine2;
49	
50	    @Column(name = "city")
51	    @NotEmpty
52	    private String city;
53	
54	    @Column(name = "telephone")
55	    @NotEmpty
56	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
57	    private String telephone;
58	
59	    @Column(name = "email")
60	    private String email;
61	
62	    @Column(name = "postcode")
63	    private String postcode;
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "household_size")
81	    private Integer householdSize;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getAddress() {
93	        return this.address;
94	    }
95	
96	    public void setAddress(String address) {
97	        this.address = address;
98	    }
99	
100	    public String getAddressLine1() {
101	        return this.addressLine1;
102	    }
103	
104	    public void setAddressLine1(String addressLine1) {
105	        this.addressLine1 = addressLine1;
106	    }
107	
108	    public String getAddressLine2() {
109	        return this.addressLine2;
110	    }
111	
112	    public void setAddressLine2(String addressLine2) {
113	        this.addressLine2 = addressLine2;
114	    }
115	
116	    public String getCity() {
117	        return this.city;
118	    }
119	
120	    public void setCity(String city) {
121	        this.city = city;
122	    }
123	
124	    public String getTelephone() {
125	        return this.telephone;
126	    }
127	
128	    public void setTelephone(String telephone) {
129	        this.telephone = telephone;
130	    }
131	
132	    /**
133	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
134	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
135	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
136	     * been set.
137	     */
138	    public String getTelephoneDisplay() {
139	        return Telephone.forDisplay(this.telephone);
140	    }
141	
142	    public String getEmail() {
143	        return this.email;
144	    }
145	
146	    public void setEmail(String email) {
147	        this.email = email;
148	    }
149	
150	    public String getPostcode() {
151	        return this.postcode;
152	    }
153	
154	    public void setPostcode(String postcode) {
155	        this.postcode = postcode;
156	    }
157	
158	    public LocalDate getRegistrationDate() {
159	        return this.registrationDate;
160	    }
161	
162	    public void setRegistrationDate(LocalDate registrationDate) {
163	        this.registrationDate = registrationDate;
164	    }
165	
166	    public LocalDate getBirthDate() {
167	        return this.birthDate;
168	    }
169	
170	    public void setBirthDate(LocalDate birthDate) {
171	        this.birthDate = birthDate;
172	    }
173	
174	    public String getCustomerCode() {
175	        return this.customerCode;
176	    }
177	
178	    public void setCustomerCode(String customerCode) {
179	        this.customerCode = customerCode;
180	    }
181	
182	    public String getHouseholdId() {
183	        return this.householdId;
184	    }
185	
186	    public void setHouseholdId(String householdId) {
187	        this.householdId = householdId;
188	    }
189	
190	    public Integer getNamesakeCount() {
191	        return this.namesakeCount;
192	    }
193	
194	    public void setNamesakeCount(Integer namesakeCount) {
195	        this.namesakeCount = namesakeCount;
196	    }
197	
198	    public Integer getHouseholdSize() {
199	        return this.householdSize;
200	    }
201	
202	    public void setHouseholdSize(Integer householdSize) {
203	        this.householdSize = householdSize;
204	    }
205	
206	    /**
207	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
208	     * postcode while holding a different telephone. Resolved at creation and stored so it is
209	     * reported consistently on every later read.
210	     */
211	    public Boolean getPossibleDuplicate() {
212	        return this.possibleDuplicate;
213	    }
214	
215	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
216	        this.possibleDuplicate = possibleDuplicate;
217	    }
218	
219	    /**
220	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
221	     * is not a possible duplicate.
222	     */
223	    public Integer getPossibleDuplicateOf() {
224	        return this.possibleDuplicateOf;
225	    }
226	
227	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
228	        this.possibleDuplicateOf = possibleDuplicateOf;
229	    }
230	
231	    /**
232	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
233	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
234	     * email or household contributes an empty string. Two owners are duplicates only when their
235	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
236	     * different telephones have distinct identity keys and are both allowed.
237	     */
238	    public String getIdentityKey() {
239	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
240	    }
241	
242	    private static String orEmpty(String value) {
243	        return value == null ? "" : value;
244	    }
245	
246	    /**
247	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
248	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
249	     * from the owner's own fields; absent until both the customer code and registration date
250	     * have been assigned.
251	     */
252	    public String getMembershipNumber() {
253	        if (this.customerCode == null || this.registrationDate == null) {
254	            return null;
255	        }
256	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
257	    }
258	
259	    /**
260	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
261	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
262	     */
263	    public Integer getCheckDigit() {
264	        if (this.customerCode == null) {
265	            return null;
266	        }
267	        return Luhn.checkDigit(this.customerCode);
268	    }
269	
270	    /**
271	     * The owner's tenure in whole days: the number of days elapsed from the
272	     * {@link #getRegistrationDate() registration date} up to today. A freshly registered owner has
273	     * a tenure of zero. Absent until a registration date is present.
274	     */
275	    public Long getTenureDays() {
276	        if (this.registrationDate == null) {
277	            return null;
278	        }
279	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
280	    }
281	
282	    /**
283	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
284	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
285	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
286	     * points once the owner's {@link #getTenureDays() tenure} exceeds 365 days.
287	     */
288	    public Integer getMembershipPoints() {
289	        int points = 0;
290	        boolean hasEmail = this.email != null && !this.email.isEmpty();
291	        if (hasEmail) {
292	            points += 2;
293	        }
294	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
295	        if (unique) {
296	            points += 1;
297	        }
298	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
299	        if (sharedHousehold) {
300	            points += 2;
301	        }
302	        Long tenureDays = getTenureDays();
303	        boolean tenured = tenureDays != null && tenureDays > 365;
304	        if (tenured) {
305	            points += 3;
306	        }
307	        return points;
308	    }
309	
310	    /**
311	     * The owner's membership level, a number from 1 to 4 derived from the owner's
312	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
313	     * 4 for 6 or more.
314	     */
315	    public Integer getMembershipLevel() {
316	        int points = getMembershipPoints();
317	        if (points >= 6) {
318	            return 4;
319	        }
320	        if (points >= 4) {
321	            return 3;
322	        }
323	        if (points >= 2) {
324	            return 2;
325	        }
326	        return 1;
327	    }
328	
329	    /**
330	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
331	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
332	     * before a customer code has been assigned.
333	     */
334	    public String getLocality() {
335	        if (this.customerCode == null) {
336	            return Regions.UNKNOWN;
337	        }
338	        int separator = this.customerCode.indexOf('-');
339	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
340	    }
341	
342	    /**
343	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
344	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
345	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
346	     */
347	    public String getTimezone() {
348	        return Regions.timezoneOf(getLocality());
349	    }
350	
351	    /**
352	     * The owner's preferred contact channel, derived from the owner's own fields:
353	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
354	     */
355	    public String getContactPreference() {
356	        boolean hasEmail = this.email != null && !this.email.isEmpty();
357	        return hasEmail ? "EMAIL" : "PHONE";
358	    }
359	
360	    /**
361	     * The owner's age band, derived from the owner's own fields: the whole years between
362	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
363	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
364	     * (65 or older). Absent until a birth date and a registration date are both present.
365	     */
366	    public String getAgeBand() {
367	        if (this.birthDate == null || this.registrationDate == null) {
368	            return null;
369	        }
370	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
371	        if (age < 18) {
372	            return "MINOR";
373	        }
374	        return age < 65 ? "ADULT" : "SENIOR";
375	    }
376	
377	    /**
